"""Saved-only438 ledger mismatch originals and exact canonical diff; no retry."""
import json,pickle,sys,time
from dataclasses import asdict
from pathlib import Path
from retry.loss389_analyze import read,save,sha
from retry.receipt421_io import load_receipt,save_receipt
from retry.canonical438 import compare
from retry.planner419 import GoalLedger,ActualObservation
from retry.planner419_model_ledger import ForecastLedger,ModelPrediction

def run(root):
 d=root/'stage438';assert not(d/'ledger-diagnosis.json').exists();cpu=time.process_time();wall=time.perf_counter();result=read(d/'result.json');assert result['status']=='ACTUAL_PAIR_CENSORED_STOP';assert result['actual'][0]['error']=='BoundaryStop: selected_first_actual_ledger_mismatch'
 path=d/'C0_decision1-before-actual-dispatch-private.json';x=load_receipt(path);trace=d/'actual_C0/trace-private.jsonl';row=json.loads(trace.read_text().splitlines()[-1]);frame=x['selected_first'];old=GoalLedger(**x['context']['ledger']);model=ForecastLedger.fork(old).advance_prediction(ModelPrediction(frame['model_progress'],old.last_clock_tick+frame['predicted']['raw_ticks'],frame['predicted']['finished']));predicted=GoalLedger(model.progress_m,model.goal_m,model.age_actions,model.last_clock_tick,model.deadline_missed,model.done);observed=old.advance_actual(ActualObservation(row['progress_after'],round(row['post']['time']*50),row['completed']));report=compare(asdict(predicted),asdict(observed));fields=[f['path'] for f in report['diffs']];assert not report['equal'] and fields==['/goal_m','/progress_m'];assert all(getattr(predicted,k)==getattr(observed,k) for k in ['age_actions','last_clock_tick','deadline_missed','done']);assert frame['memory_before']==row['memory_before'] and frame['memory_after']==row['nominal_memory_after'];assert x['record']['canonical_adapter']['equal']
 fidelity=read(d/'actual_C0/fidelity-checks.json')[-1];assert fidelity['passed'] and fidelity['wheel']['clipped_flag_mismatches']==0;assert result['actual'][0]['actual_commits']==0 and result['actual'][0]['actual_ledger']==asdict(old)
 payload=dict(original_left_pickle=pickle.dumps(asdict(predicted),protocol=5),original_right_pickle=pickle.dumps(asdict(observed),protocol=5),original_prediction_frame_pickle=pickle.dumps(frame,protocol=5),original_observed_row_pickle=pickle.dumps(row,protocol=5),original_context_pickle=pickle.dumps(x['context'],protocol=5),normalized=report,scope='Post-stop exact pure reconstruction from recorded model frame/root and observed native row using unchanged ledger functions. Neither observed candidate nor model candidate was committed.',input_hashes={str(path):sha(path),str(trace):sha(trace)},new_worlds=0,new_actual_actions=0)
 target=d/'C0_decision1-ledger-mismatch-private.json';save_receipt(target,payload);saved=load_receipt(target);assert saved['original_left_pickle']==payload['original_left_pickle'] and saved['original_right_pickle']==payload['original_right_pickle']
 q=dict(stage=438,kind='EXACT_LEDGER_VS_REGISTERED_BODY_TOLERANCE',canonical_snapshot_adapter_passed=True,actual_body_wheel_raw_hull_checks_passed=True,memory_exact=True,clipping_mismatches=0,changed_ledger_fields=fields,model_minus_observed_progress_m=predicted.progress_m-observed.progress_m,model_minus_observed_goal_m=predicted.goal_m-observed.goal_m,other_ledger_fields_exact=True,model_and_actual_both_reached_same_root_goal=True,actual_ledger_unchanged_after_rejection=True,actual_DONE=False,observed_candidate_committed=False,model_candidate_committed=False,first_transition=fidelity,actual_suffix_force_max=result['actual'][0]['suffix_max_force_ratio'],mismatch_originals_and_canonical_field_diff_saved=True,private_mismatch_sha256=sha(target),source_unchanged_since_model_start=True,post_stop_model_ticks=0,post_stop_actual_actions=0,actual_retry=False,scope='One new C0 nominal transition only; exact ledger gate stricter than nonzero physical fidelity tolerances. No threshold relaxation or numeric rounding, no P/high-force/pending or completion qualification.',diagnostic_source_sha256=sha(Path(__file__)),CPU_s=time.process_time()-cpu,wall_s=time.perf_counter()-wall);save(d/'ledger-diagnosis.json',q);print(json.dumps({k:q[k] for k in ['changed_ledger_fields','model_minus_observed_progress_m','canonical_snapshot_adapter_passed','actual_body_wheel_raw_hull_checks_passed','actual_ledger_unchanged_after_rejection','actual_retry']}))
if __name__=='__main__':run(Path(sys.argv[1]))
